import z3

s = z3.Solver()

d = [[z3.Int(f"d_{i}_{j}") for j in range(6)] for i in range(5)]

for i in range(5):
    for j in range(6):
        s.add(d[i][j] >= 0, d[i][j] <= 11)
    for j in range(5):
        s.add(d[i][j] <= d[i][j+1])

for i in range(5):
    i_next = (i+1) % 5
    win_sum = z3.Sum([z3.If(d[i][a] > d[i_next][b], 1, 0) for a in range(6) for b in range(6)])
    s.add(win_sum >= 19)

print("Solving...")
result = s.check()
print("Result:", result)

if result == z3.sat:
    model = s.model()
    flat = []
    for i in range(5):
        die = sorted([model.evaluate(d[i][j]).as_long() for j in range(6)])
        flat.extend(die)
        print(f"Die {i}: {die}")
    print("Flat:", flat)

    # Verify
    def count_wins(die1, die2):
        wins = 0
        for a in die1:
            for b in die2:
                if a > b:
                    wins += 1
        return wins

    dice = [flat[i*6:(i+1)*6] for i in range(5)]
    for i in range(5):
        w = count_wins(dice[i], dice[(i+1)%5])
        print(f"Die {i} vs Die {(i+1)%5}: {w} wins (need >18)")
else:
    print("UNSAT")
